   178→        @JvmStatic
   179→        fun loadDictionary(baseFile: File, dictProp: JSONObject): ProductNameDictionary {
   180→            var dictionary: Dictionary<TagProb, PreResult<CharSequence>>? = null
   181→            var commonDictionary: ProductNameDictionary? = null
   182→            val dictList = dictProp.optJSONArray(ATTR_DICTIONARY_LIST)
   183→            val basePath = dictProp.optString(ATTR_DICTIONARY_BASE_PATH)
   184→
   185→            for (inx in 0 until dictList.length()) {
   186→                val row = dictList.optJSONObject(inx)
   187→                if (getType(row) == Type.SYSTEM) {
   188→                    dictionary = loadSystemDictionary(baseFile, row, basePath)
   189→                    commonDictionary = ProductNameDictionary(dictionary)
   190→                    break
   191→                }
   192→            }
   193→
   194→            for (inx in 0 until dictList.length()) {
   195→                val row = dictList.optJSONObject(inx)
   196→                val dictionaryId = row.optString(ATTR_DICTIONARY_NAME)
   197→                val type = getType(row)
   198→                val tokenType = getTokenType(row)
   199→                val label = getLabel(row)
   200→                val seq = getSeq(row)
   201→                val dictFile = getDictionaryFile(baseFile, row, basePath)
   202→                val ignoreCase = getIgnoreCase(row)
   203→                var sourceDictionary: SourceDictionary<*>? = null
   204→                logger.info("Dictionary Setting Name: {}, type: {}", label, type!!.name)
   205→
   206→                when (type) {
   207→                    Type.SET -> {
   208→                        val setDictionary = SetDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
   209→                        if (tokenType != null) {
   210→                            commonDictionary!!.appendAdditionalNounEntry(setDictionary.set(), tokenType)
   211→                        }
   212→                        sourceDictionary = setDictionary
   213→                    }
   214→                    Type.MAP -> {
   215→                        val mapDictionary = MapDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
   216→                        if (tokenType != null) {
   217→                            commonDictionary!!.appendAdditionalNounEntry(mapDictionary.map().keys, tokenType)
   218→                        }
   219→                        sourceDictionary = mapDictionary
   220→                    }
   221→                    Type.SYNONYM, Type.SYNONYM_2WAY -> {
   222→                        val synonymDictionary = SynonymDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
   223→                        if (tokenType != null) {
   224→                            commonDictionary!!.appendAdditionalNounEntry(synonymDictionary.getWordSet(), tokenType)
   225→                        }
   226→                        sourceDictionary = synonymDictionary
   227→                    }
   228→                    Type.SPACE -> {
   229→                        val spaceDictionary = SpaceDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
   230→                        if (tokenType != null) {
   231→                            commonDictionary!!.appendAdditionalNounEntry(spaceDictionary.getWordSet(), tokenType)
   232→                            val map = HashMap<CharSequence, PreResult<CharSequence>>()
   233→                            for (e in spaceDictionary.map().entries) {
   234→                                val preResult = PreResult<CharSequence>()
   235→                                preResult.setResult(e.value)
   236→                                map[e.key] = preResult
   237→                            }
   238→                        }
   239→                        sourceDictionary = spaceDictionary
   240→                    }
   241→                    Type.CUSTOM -> {
   242→                        val customDictionary = CustomDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
   243→                        if (tokenType != null) {
   244→                            commonDictionary!!.appendAdditionalNounEntry(customDictionary.getWordSet(), tokenType)
   245→                        }
   246→                        sourceDictionary = customDictionary
   247→                    }
   248→                    Type.INVERT_MAP -> {
   249→                        val invertMapDictionary = InvertMapDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
   250→                        if (tokenType != null) {
   251→                            commonDictionary!!.appendAdditionalNounEntry(invertMapDictionary.map().keys, tokenType)
   252→                        }
   253→                        sourceDictionary = invertMapDictionary
   254→                    }
   255→                    Type.COMPOUND -> {
   256→                        val compoundDictionary = CompoundDictionary(dictFile, ignoreCase, label, seq, tokenType, type)
   257→                        if (tokenType != null) {
   258→                            commonDictionary!!.appendAdditionalNounEntry(compoundDictionary.map().keys, tokenType)
   259→                        }
   260→                        sourceDictionary = compoundDictionary
   261→                    }
   262→                    Type.SYSTEM -> { /* ignore */ }
   263→                }
   264→                if (sourceDictionary != null) {
   265→                    commonDictionary!!.addDictionary(dictionaryId, sourceDictionary)
   266→                }
   267→            }
   268→            return commonDictionary!!
   269→        }
