   271→        @JvmStatic
   272→        fun reloadDictionary() {
   273→            if (baseFile == null || configFile == null) {
   274→                logger.error("DICTIONARY NOT LOADED!")
   275→                return
   276→            }
   277→            val newCommonDictionary = loadDictionary(baseFile!!, ResourceResolver.readYmlConfig(configFile))
   278→            val commonDictionary = contextStore.getAs(PRODUCT_NAME_DICTIONARY, ProductNameDictionary::class.java)
   279→            commonDictionary.reset(newCommonDictionary)
   280→            val dictionaryMap = commonDictionary.getDictionaryMap()
   281→
   282→            for ((dictionaryId, dictionary) in dictionaryMap) {
   283→                if (dictionary.javaClass.isAssignableFrom(SetDictionary::class.java)) {
   284→                    val setDictionary = dictionary as SetDictionary
   285→                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, SetDictionary::class.java)
   286→                    setDictionary.setSet(newDictionary.set())
   287→                } else if (dictionary.javaClass.isAssignableFrom(MapDictionary::class.java)) {
   288→                    val mapDictionary = dictionary as MapDictionary
   289→                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, MapDictionary::class.java)
   290→                    mapDictionary.setMap(newDictionary.map())
   291→                } else if (dictionary.javaClass.isAssignableFrom(SynonymDictionary::class.java)) {
   292→                    val synonymDictionary = dictionary as SynonymDictionary
   293→                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, SynonymDictionary::class.java)
   294→                    synonymDictionary.setMap(newDictionary.map())
   295→                    synonymDictionary.setWordSet(newDictionary.getWordSet())
   296→                } else if (dictionary.javaClass.isAssignableFrom(SpaceDictionary::class.java)) {
   297→                    val spaceDictionary = dictionary as SpaceDictionary
   298→                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, SpaceDictionary::class.java)
   299→                    spaceDictionary.setMap(newDictionary.map())
   300→                    spaceDictionary.setWordSet(newDictionary.getWordSet())
   301→                } else if (dictionary.javaClass.isAssignableFrom(CustomDictionary::class.java)) {
   302→                    val customDictionary = dictionary as CustomDictionary
   303→                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, CustomDictionary::class.java)
   304→                    customDictionary.setMap(newDictionary.map())
   305→                    customDictionary.setWordSet(newDictionary.getWordSet())
   306→                } else if (dictionary.javaClass.isAssignableFrom(CompoundDictionary::class.java)) {
   307→                    val compoundDictionary = dictionary as CompoundDictionary
   308→                    val newDictionary = newCommonDictionary.getDictionary(dictionaryId, CompoundDictionary::class.java)
   309→                    compoundDictionary.setMap(newDictionary.map())
   310→                }
   311→                logger.info("Dictionary [{}] is reloaded!", dictionaryId)
   312→            }
   313→        }
