   315→        @JvmStatic
   316→        fun compileDictionary(client: NodeClient, repo: DictionaryRepository, filter: String?, exportFile: Boolean) {
   317→            if (baseFile == null || configFile == null) {
   318→                logger.error("DICTIONARY NOT LOADED!")
   319→            }
   320→
   321→            val filters = HashSet<String>()
   322→            if (filter != null) {
   323→                val split = filter.trim { it <= ' ' }.split(",")
   324→                for (item in split) {
   325→                    filters.add(item.lowercase())
   326→                }
   327→            }
   328→            logger.info("Compile Dict types: {}", filters)
   329→
   330→            val dictProp = ResourceResolver.readYmlConfig(configFile)
   331→            val dictList = dictProp.optJSONArray(ATTR_DICTIONARY_LIST)
   332→            val basePath = dictProp.optString(ATTR_DICTIONARY_BASE_PATH)
   333→
   334→            for (inx in 0 until dictList.length()) {
   335→                val row = dictList.optJSONObject(inx)
   336→                val dictionaryId = row.optString(ATTR_DICTIONARY_NAME)
   337→
   338→                if (filters.size > 0 && !filters.contains(dictionaryId)) {
   339→                    continue
   340→                }
   341→
   342→                val compileDictMap = compileDictionaryOne(repo, dictList, dictionaryId)
   343→                val sourceDictionary = compileDictMap?.get("dict") as? SourceDictionary<*>
   344→                if (sourceDictionary != null) {
   345→                    SearchUtil.upsertData(client, ".dsearch_dict_apply", compileDictMap)
   346→
   347→                    if (exportFile) {
   348→                        val dictFile = getDictionaryFile(baseFile!!, row, basePath)
   349→                        var ostream: java.io.OutputStream? = null
   350→                        try {
   351→                            ostream = FileOutputStream(dictFile)
   352→                            sourceDictionary.writeTo(ostream)
   353→                            logger.info("DICTIONARY FILE SAVED! {} / {}", dictionaryId, dictFile.absolutePath)
   354→                        } catch (ignore: Exception) {
   355→                        } finally {
   356→                            try { ostream?.close() } catch (ignore: Exception) { }
   357→                        }
   358→                    }
   359→                }
   360→            }
   361→            logger.debug("DICTIONARY LOAD COMPLETE! [{}]", if (filter == null) "ALL" else filter)
   362→        }
