   364→        @JvmStatic
   365→        fun compileDictionaryOne(repo: DictionaryRepository, dictList: JSONArray, dictionaryId: String): MutableMap<String, Any?>? {
   366→            val result = HashMap<String, Any?>()
   367→
   368→            for (inx in 0 until dictList.length()) {
   369→                val row = dictList.optJSONObject(inx)
   370→                val dictId = row.optString(ATTR_DICTIONARY_NAME)
   371→                if (dictionaryId != dictId) {
   372→                    continue
   373→                }
   374→                val type = getType(row)
   375→                val tokenType = getTokenType(row)
   376→                val label = getLabel(row)
   377→                val seq = getSeq(row)
   378→                val ignoreCase = row.optBoolean(ATTR_DICTIONARY_IGNORECASE, true)
   379→
   380→                val source = repo.getSource(dictionaryId)
   381→
   382→                var sourceDictionary: SourceDictionary<*>? = when (type) {
   383→                    Type.SET -> SetDictionary(ignoreCase)
   384→                    Type.MAP -> MapDictionary(ignoreCase)
   385→                    Type.SYNONYM, Type.SYNONYM_2WAY -> SynonymDictionary(ignoreCase)
   386→                    Type.SPACE -> SpaceDictionary(ignoreCase)
   387→                    Type.CUSTOM -> CustomDictionary(ignoreCase)
   388→                    Type.INVERT_MAP -> InvertMapDictionary(ignoreCase)
   389→                    Type.COMPOUND -> CompoundDictionary(ignoreCase)
   390→                    else -> null
   391→                }
   392→
   393→                if (sourceDictionary != null) {
   394→                    var cnt = 0
   395→                    while (source.hasNext()) {
   396→                        val data = source.next()
   397→                        var id = ""
   398→                        var keyword = ""
   399→                        var value = ""
   400→                        var line: String
   401→                        if (data[0] != null) { id = data[0].toString().trim { it <= ' ' } }
   402→                        if (data[1] != null) { keyword = data[1].toString().trim { it <= ' ' } }
   403→                        if (data[2] != null) { value = data[2].toString().trim { it <= ' ' } }
   404→                        line = when {
   405→                            type == Type.SYNONYM || type == Type.SYNONYM_2WAY -> {
   406→                                if (keyword.isNotEmpty()) "$keyword\t$value" else value
   407→                            }
   408→                            type == Type.CUSTOM -> {
   409→                                if (id.isNotEmpty()) "$keyword\t$id" else keyword
   410→                            }
   411→                            else -> {
   412→                                if (value.isNotEmpty()) "$keyword\t$value" else keyword
   413→                            }
   414→                        }
   415→                        sourceDictionary.addSourceLineEntry(line)
   416→                        cnt++
   417→                    }
   418→                    result["cnt"] = cnt
   419→                    logger.info("DICTIONARY LOADED! [{}] / {} / {} / {}", cnt, dictionaryId, type, tokenType)
   420→                }
   421→                result["dict"] = sourceDictionary
   422→                result["type"] = dictId
   423→                result["id"] = dictId
   424→                return result
   425→            }
   426→            return null
   427→        }
