   467→        fun getTwowaySynonymWord(mainWord: CharSequence, synonymMap: Map<CharSequence, Array<CharSequence>>): List<CharSequence>? {
   468→            val map = HashMap<CharSequence, MutableList<CharSequence>>()
   469→            val keys = ArrayList<CharSequence>()
   470→            var values: MutableList<CharSequence>
   471→            values = ArrayList()
   472→            map[mainWord] = values
   473→            keys.addAll(map.keys)
   474→            values.addAll(Arrays.asList(*synonymMap[mainWord]!!))
   475→
   476→            var kinx = 0
   477→            while (kinx < keys.size) {
   478→                val word = keys[kinx]
   479→                val synonyms = synonymMap[word]
   480→                logger.trace("SYN {} : {}", word, synonyms)
   481→                if (synonyms != null) {
   482→                    for (sinx in synonyms.indices) {
   483→                        val synonym = synonyms[sinx]
   484→                        if (keys.contains(synonym)) continue
   485→                        val subSynonyms = synonymMap[synonym]
   486→                        if (subSynonyms != null && synonyms.isNotEmpty()) {
   487→                            for (subSynonym in subSynonyms) {
   488→                                if (mainWord == subSynonym) {
   489→                                    values = ArrayList()
   490→                                    map[synonym] = values
   491→                                    keys.add(synonym)
   492→                                    values.addAll(Arrays.asList(*subSynonyms))
   493→                                    break
   494→                                }
   495→                            }
   496→                        }
   497→                    }
   498→                }
   499→                kinx++
   500→            }
   501→            if (map.size > 1) {
   502→                normalizeSynonymMap(map)
   503→            }
   504→            logger.trace("MAP:{}", map)
   505→            if (map.size > 1) {
   506→                keys.clear()
   507→                keys.addAll(TreeSet(map.keys))
   508→                return keys
   509→            }
   510→            return null
   511→        }
