   513→        @JvmStatic
   514→        fun normalizeSynonymMap(map: MutableMap<CharSequence, MutableList<CharSequence>>) {
   515→            val keys = ArrayList<CharSequence>()
   516→            keys.addAll(map.keys)
   517→            for (inx in keys.indices) {
   518→                val word = keys[inx]
   519→                val values = map[word]!!
   520→                var vinx = 0
   521→                while (vinx < values.size) {
   522→                    val value = values[vinx]
   523→                    if (!keys.contains(value)) {
   524→                        values.removeAt(vinx)
   525→                        vinx--
   526→                    }
   527→                    vinx++
   528→                }
   529→            }
   530→            val delete = ArrayList<CharSequence>()
   531→            logger.trace("MAP:{}", map)
   532→            for (sinx in keys.indices) {
   533→                val word = keys[sinx]
   534→                for (tinx in keys.indices) {
   535→                    if (sinx == tinx) continue
   536→                    val values = map[keys[tinx]]!!
   537→                    if (!values.contains(word)) {
   538→                        delete.add(word)
   539→                        break
   540→                    }
   541→                }
   542→            }
   543→            for (key in delete) {
   544→                map.remove(key)
   545→            }
   546→            logger.trace("MAP:{}", map)
   547→        }
