   196→	public static ProductNameDictionary loadDictionary(final File baseFile, final JSONObject dictProp) {
   197→		/**
   198→		 * 기본셋팅.
   199→		 * ${ELASTICSEARCH}/config/product_name_analysis.prop 파일을 사용하도록 한다
   200→		 * NORI 기분석 사전은 기본적으로(수정불가) 사용하되 사용자 사전을 활용하여
   201→		 * 커스터마이징 하도록 한다.
   202→		 * 우선은 JAXB 마샬링 구조를 사용하지 않고 Properties 를 사용하도록 한다.
   203→		 **/
   204→		Dictionary<TagProb, PreResult<CharSequence>> dictionary = null;
   205→		ProductNameDictionary commonDictionary = null;
   206→		JSONArray dictList = dictProp.optJSONArray(ATTR_DICTIONARY_LIST);
   207→		String basePath = dictProp.optString(ATTR_DICTIONARY_BASE_PATH);
   208→
   209→		// 시스템사전을 먼저 읽어오도록 한다.
   210→		for (int inx = 0; inx < dictList.length(); inx++) {
   211→			JSONObject row = dictList.optJSONObject(inx);
   212→			if (getType(row) == Type.SYSTEM) {
   213→				dictionary = loadSystemDictionary(baseFile, row, basePath);
   214→				commonDictionary = new ProductNameDictionary(dictionary);
   215→				break;
   216→			}
   217→		}
   218→
   219→		for (int inx = 0; inx < dictList.length(); inx++) {
   220→			JSONObject row = dictList.optJSONObject(inx);
   221→			String dictionaryId = row.optString(ATTR_DICTIONARY_NAME);
   222→			Type type = getType(row);
   223→			String tokenType = getTokenType(row);
   224→			String label = getLabel(row);
   225→			int seq = getSeq(row);
   226→			File dictFile = getDictionaryFile(baseFile, row, basePath);
   227→			boolean ignoreCase = getIgnoreCase(row);
   228→			SourceDictionary<?> sourceDictionary = null;
   229→			logger.info("Dictionary Setting Name: {}, type: {}", label, type.name());
   230→
   231→			if (type == Type.SET) {
   232→				SetDictionary setDictionary = new SetDictionary(dictFile, ignoreCase, label, seq, tokenType, type);
   233→				if (tokenType != null) {
   234→					commonDictionary.appendAdditionalNounEntry(setDictionary.set(), tokenType);
   235→				}
   236→				sourceDictionary = setDictionary;
   237→			} else if (type == Type.MAP) {
   238→				MapDictionary mapDictionary = new MapDictionary(dictFile, ignoreCase, label, seq, tokenType, type);
   239→				if (tokenType != null) {
   240→					commonDictionary.appendAdditionalNounEntry(mapDictionary.map().keySet(), tokenType);
   241→				}
   242→				sourceDictionary = mapDictionary;
   243→			} else if (type == Type.SYNONYM || type == Type.SYNONYM_2WAY) {
   244→				SynonymDictionary synonymDictionary = new SynonymDictionary(dictFile, ignoreCase, label, seq, tokenType, type);
   245→				if (tokenType != null) {
   246→					commonDictionary.appendAdditionalNounEntry(synonymDictionary.getWordSet(), tokenType);
   247→				}
   248→				sourceDictionary = synonymDictionary;
   249→			} else if (type == Type.SPACE) {
   250→				SpaceDictionary spaceDictionary = new SpaceDictionary(dictFile, ignoreCase, label, seq, tokenType, type);
   251→				if (tokenType != null) {
   252→					commonDictionary.appendAdditionalNounEntry(spaceDictionary.getWordSet(), tokenType);
   253→					Map<CharSequence, PreResult<CharSequence>> map = new HashMap<>();
   254→					for (Entry<CharSequence, CharSequence[]> e : spaceDictionary.map().entrySet()) {
   255→						PreResult<CharSequence> preResult = new PreResult<>();
   256→						preResult.setResult(e.getValue());
   257→						map.put(e.getKey(), preResult);
   258→					}
   259→					// commonDictionary.setPreDictionary(map);
   260→				}
   261→				sourceDictionary = spaceDictionary;
   262→			} else if (type == Type.CUSTOM) {
   263→				CustomDictionary customDictionary = new CustomDictionary(dictFile, ignoreCase, label, seq, tokenType, type);
   264→				if (tokenType != null) {
   265→					commonDictionary.appendAdditionalNounEntry(customDictionary.getWordSet(), tokenType);
   266→				}
   267→				sourceDictionary = customDictionary;
   268→			} else if (type == Type.INVERT_MAP) {
   269→				InvertMapDictionary invertMapDictionary = new InvertMapDictionary(dictFile, ignoreCase, label, seq, tokenType, type);
   270→				if (tokenType != null) {
   271→					commonDictionary.appendAdditionalNounEntry(invertMapDictionary.map().keySet(), tokenType);
   272→				}
   273→				sourceDictionary = invertMapDictionary;
   274→			} else if (type == Type.COMPOUND) {
   275→				CompoundDictionary compoundDictionary = new CompoundDictionary(dictFile, ignoreCase, label, seq, tokenType, type);
   276→				if (tokenType != null) {
   277→					commonDictionary.appendAdditionalNounEntry(compoundDictionary.map().keySet(), tokenType);
   278→				}
   279→				sourceDictionary = compoundDictionary;
   280→			} else if (type == Type.SYSTEM) {
   281→				// ignore
   282→			} else {
   283→				logger.error("Unknown Dictionary type > {}", type);
   284→			}
   285→			if (sourceDictionary != null) {
   286→				commonDictionary.addDictionary(dictionaryId, sourceDictionary);
   287→			}
   288→		}
   289→		return commonDictionary;
   290→	}
