   527→	public static List<CharSequence> getTwowaySynonymWord(CharSequence mainWord, Map<CharSequence, CharSequence[]> synonymMap) {
   528→		CharSequence word = null;
   529→		Map<CharSequence, List<CharSequence>> map = new HashMap<>();
   530→		List<CharSequence> keys = new ArrayList<>();
   531→		List<CharSequence> values = null;
   532→		CharSequence[] synonyms = null;
   533→		CharSequence[] subSynonyms = null;
   534→		map.put(mainWord, values = new ArrayList<>());
   535→		keys.addAll(map.keySet());
   536→		values.addAll(Arrays.asList(synonymMap.get(mainWord)));
   537→
   538→		for (int kinx = 0; kinx < keys.size(); kinx++) {
   539→			word = keys.get(kinx);
   540→			synonyms = synonymMap.get(word);
   541→			logger.trace("SYN {} : {}", word, synonyms);
   542→
   543→			for (int sinx = 0; sinx < synonyms.length; sinx++) {
   544→				CharSequence synonym = synonyms[sinx];
   545→				if (keys.contains(synonym)) { continue; }
   546→				subSynonyms = synonymMap.get(synonym);
   547→				if (subSynonyms != null && synonyms.length > 0) {
   548→					for (CharSequence subSynonym : subSynonyms) {
   549→						if (mainWord.equals(subSynonym)) {
   550→							map.put(synonym, values = new ArrayList<>());
   551→							keys.add(synonym);
   552→							values.addAll(Arrays.asList(subSynonyms));
   553→							break;
   554→						}
   555→					}
   556→				}
   557→			}
   558→		}
   559→		if (map.size() > 1) {
   560→			normalizeSynonymMap(map);
   561→		}
   562→		logger.trace("MAP:{}", map);
   563→		if (map.size() > 1) {
   564→			keys.clear();
   565→			keys.addAll(new TreeSet<CharSequence>(map.keySet()));
   566→			return keys;
   567→		}
   568→		return null;
   569→	}
