   571→	public static void normalizeSynonymMap(Map<CharSequence, List<CharSequence>> map) {
   572→		CharSequence word = null;
   573→		List<CharSequence> keys = new ArrayList<>();
   574→		List<CharSequence> values = null;
   575→		keys.addAll(map.keySet());
   576→		// 키값에 없는 동의어 제거
   577→		for (int inx = 0; inx < keys.size(); inx++) {
   578→			word = keys.get(inx);
   579→			values = map.get(word);
   580→			for (int vinx = 0; vinx < values.size(); vinx++) {
   581→				CharSequence value = values.get(vinx);
   582→				if (!keys.contains(value)) {
   583→					values.remove(vinx);
   584→					vinx--;
   585→				}
   586→			}
   587→		}
   588→		List<CharSequence> delete = new ArrayList<>();
   589→		// 동의어에 없는 키값 제거
   590→		logger.trace("MAP:{}", map);
   591→		for (int sinx = 0; sinx < keys.size(); sinx++) {
   592→			word = keys.get(sinx);
   593→			for (int tinx = 0; tinx < keys.size(); tinx++) {
   594→				if (sinx == tinx) { continue; }
   595→				values = map.get(keys.get(tinx));
   596→				if (!values.contains(word)) {
   597→					delete.add(word);
   598→					break;
   599→				}
   600→			}
   601→		}
   602→		for (CharSequence key : delete) {
   603→			map.remove(key);
   604→		}
   605→		logger.trace("MAP:{}", map);
   606→	}
