   608→	public static boolean isOneWaySynonym(CharSequence word, Map<CharSequence, CharSequence[]> map) {
   609→		if (map.containsKey(word)) {
   610→			List<CharSequence> twoway = getTwowaySynonymWord(word, map);
   611→			logger.trace("TWO-WAY {} = {}", word, twoway);
   612→			for (CharSequence value : map.get(word)) {
   613→				if (twoway != null && twoway.contains(value)) { continue; }
   614→				// 단방향이 하나라도 있으면 단방향 동의어
   615→				logger.trace("ONE-WAY {} -> {}", word, value);
   616→				return true;
   617→			}
   618→		}
   619→		return false;
   620→	}
