   622→	public static void restoreDictionary(final DictionaryRepository repo, String index) {
   623→		ProductNameDictionary productNameDictionary = contextStore.getAs(PRODUCT_NAME_DICTIONARY, ProductNameDictionary.class);
   624→		Map<String, SourceDictionary<?>> dictionaryMap = productNameDictionary.getDictionaryMap();
   625→		Set<String> keySet = dictionaryMap.keySet();
   626→		for (String key : keySet) {
   627→			SourceDictionary<?> sourceDictionary = dictionaryMap.get(key);
   628→			logger.debug("KEY:{} / {}", key, sourceDictionary);
   629→			if (sourceDictionary.getClass().isAssignableFrom(SetDictionary.class)) {
   630→				SetDictionary dictionary = (SetDictionary) sourceDictionary;
   631→				Set<CharSequence> words = dictionary.set();
   632→				repo.restore(key, dictionary.ignoreCase(), words);
   633→			} else if (sourceDictionary.getClass().isAssignableFrom(MapDictionary.class)) {
   634→				MapDictionary dictionary = (MapDictionary) sourceDictionary;
   635→				Set<CharSequence> words = new HashSet<>();
   636→				Map<CharSequence, CharSequence[]> map = dictionary.map();
   637→				for (CharSequence word : map.keySet()) {
   638→					StringBuilder sb = new StringBuilder();
   639→					for (CharSequence value : map.get(word)) {
   640→						if (sb.length() > 0) { sb.append(","); }
   641→						sb.append(String.valueOf(value).trim());
   642→					}
   643→					words.add(String.valueOf(word) + TAB + String.valueOf(sb));
   644→				}
   645→				repo.restore(key, dictionary.ignoreCase(), words);
   646→			} else if (sourceDictionary.getClass().isAssignableFrom(SynonymDictionary.class)) {
   647→				SynonymDictionary dictionary = (SynonymDictionary) sourceDictionary;
   648→				Set<CharSequence> words = new HashSet<>();
   649→				Map<CharSequence, CharSequence[]> map = dictionary.map();
   650→				for (CharSequence word : map.keySet()) {
   651→					List<CharSequence> twoway = getTwowaySynonymWord(word, map);
   652→					{
   653→						// 단방향 동의어에서 양방향을 뺀 나머지 값들만 저장한다.
   654→						StringBuilder sb = new StringBuilder();
   655→						for (CharSequence value : map.get(word)) {
   656→							if (twoway != null && twoway.contains(value)) { continue; }
   657→							if (sb.length() > 0) { sb.append(","); }
   658→							sb.append(String.valueOf(value).trim());
   659→						}
   660→						if (sb.length() > 0) {
   661→							words.add(String.valueOf(word) + TAB + String.valueOf(sb));
   662→						}
   663→					}
   664→					if (twoway != null && twoway.size() > 0) {
   665→						// 양방향 동의어를 저장한다.
   666→						StringBuilder sb = new StringBuilder();
   667→						for (CharSequence value : twoway) {
   668→							if (sb.length() > 0) { sb.append(","); }
   669→							sb.append(String.valueOf(value).trim());
   670→						}
   671→						if (sb.length() > 0) {
   672→							words.add(TAB + String.valueOf(sb));
   673→						}
   674→					}
   675→				}
   676→				repo.restore(key, dictionary.ignoreCase(), words);
   677→			} else if (sourceDictionary.getClass().isAssignableFrom(SpaceDictionary.class)) {
   678→				SpaceDictionary dictionary = (SpaceDictionary) sourceDictionary;
   679→				Set<CharSequence> words = new HashSet<>();
   680→				Map<CharSequence, CharSequence[]> map = dictionary.map();
   681→				for (CharSequence word : map.keySet()) {
   682→					StringBuilder sb = new StringBuilder();
   683→					for (CharSequence value : map.get(word)) {
   684→						if (sb.length() > 0) { sb.append(" "); }
