   689→				repo.restore(key, dictionary.ignoreCase(), words);
   690→			} else if (sourceDictionary.getClass().isAssignableFrom(CustomDictionary.class)) {
   691→				CustomDictionary dictionary = (CustomDictionary) sourceDictionary;
   692→				Set<CharSequence> words = new HashSet<>();
   693→				Map<CharSequence, Object[]> map = dictionary.map();
   694→				for (CharSequence word : map.keySet()) {
   695→					StringBuilder sb = new StringBuilder();
   696→					for (Object value : map.get(word)) {
   697→						if (value != null) {
   698→							if (sb.length() > 0) { sb.append(","); }
   699→							sb.append(String.valueOf(value).trim());
   700→						}
   701→					}
   702→					words.add(String.valueOf(word) + TAB + String.valueOf(word) + TAB + String.valueOf(sb));
   703→				}
   704→				repo.restore(key, dictionary.ignoreCase(), words);
   705→			} else if (sourceDictionary.getClass().isAssignableFrom(InvertMapDictionary.class)) {
   706→				InvertMapDictionary dictionary = (InvertMapDictionary) sourceDictionary;
   707→				Set<CharSequence> words = new HashSet<>();
   708→				Map<CharSequence, CharSequence[]> map = dictionary.map();
   709→				for (CharSequence word : map.keySet()) {
   710→					StringBuilder sb = new StringBuilder();
