   110→     * 각 노드에서 실행되는 핵심 로직
   111→     */
   112→    @Override
   113→    protected ReloadDictNodeResponse nodeOperation(ReloadDictNodeRequest request, Task task) {
   114→        DiscoveryNode localNode = clusterService.localNode();
   115→        long startTime = System.currentTimeMillis();
   116→
   117→        try {
   118→            logger.info("[{}] Dictionary reload started, type={}",
   119→                localNode.getName(), request.getDictionaryType());
   120→
   121→            // 사전 인스턴스 확인
   122→            if (!contextStore.containsKey(ProductNameDictionary.PRODUCT_NAME_DICTIONARY)) {
   123→                logger.warn("[{}] Dictionary not initialized", localNode.getName());
   124→                return new ReloadDictNodeResponse(
   125→                    localNode, false, "Dictionary not initialized", 0, 0
   126→                );
   127→            }
   128→
   129→            ProductNameDictionary dictionary = contextStore.getAs(
   130→                ProductNameDictionary.PRODUCT_NAME_DICTIONARY,
   131→                ProductNameDictionary.class
   132→            );
   133→
   134→            if (dictionary == null) {
   135→                return new ReloadDictNodeResponse(
   136→                    localNode, false, "Dictionary instance is null", 0, 0
   137→                );
   138→            }
   139→
   140→            // 사전 리로드 실행
   141→            ProductNameDictionary.reloadDictionary();
   142→
   143→            long elapsed = System.currentTimeMillis() - startTime;
   144→            int size = getDictionarySize(dictionary);
   145→
   146→            logger.info("[{}] Dictionary reload completed in {}ms, size={}",
   147→                localNode.getName(), elapsed, size);
   148→
   149→            return new ReloadDictNodeResponse(
   150→                localNode, true, "Reload successful", elapsed, size
   151→            );
   152→
   153→        } catch (Exception e) {
   154→            long elapsed = System.currentTimeMillis() - startTime;
   155→            logger.error("[{}] Dictionary reload failed: {}", localNode.getName(), e.getMessage(), e);
   156→
   157→            return new ReloadDictNodeResponse(
   158→                localNode, false, e.getMessage(), elapsed, 0
   159→            );
   160→        }
   161→    }
