   167→        try {
   168→            if (dictionary.getDictionaryMap() != null) {
   169→                return dictionary.getDictionaryMap().size();
   170→            }
   171→        } catch (Exception e) {
   172→            logger.debug("Failed to get dictionary size", e);
   173→        }
   174→        return 0;
   175→    }
   176→}
