    13→
    14→/**
    15→ * 클러스터 전체 노드의 사전 리로드 응답
    16→ * ES 9.x: BaseNodesResponse로 노드별 결과 집계
    17→ */
    18→public class ReloadDictNodesResponse extends BaseNodesResponse<ReloadDictNodeResponse>
    19→        implements ToXContentObject {
    20→
    21→    public ReloadDictNodesResponse(ClusterName clusterName,
    22→                                   List<ReloadDictNodeResponse> nodes,
    23→                                   List<FailedNodeException> failures) {
    24→        super(clusterName, nodes, failures);
    25→    }
    26→
    27→    /**
    28→     * ES 9.x 필수: Writeable.Reader 기반 역직렬화
    29→     */
    30→    public ReloadDictNodesResponse(StreamInput in) throws IOException {
    31→        super(in);
    32→    }
    33→
    34→    @Override
    35→    protected List<ReloadDictNodeResponse> readNodesFrom(StreamInput in) throws IOException {
    36→        return in.readCollectionAsList(ReloadDictNodeResponse::new);
    37→    }
    38→
    39→    @Override
    40→    protected void writeNodesTo(StreamOutput out, List<ReloadDictNodeResponse> nodes) throws IOException {
    41→        out.writeCollection(nodes);
    42→    }
    43→
    44→    @Override
    45→    public XContentBuilder toXContent(XContentBuilder builder, Params params) throws IOException {
    46→        builder.startObject();
    47→        builder.field("cluster_name", getClusterName().value());
    48→
    49→        // 노드별 결과
    50→        builder.startArray("nodes");
    51→        for (ReloadDictNodeResponse nodeResp : getNodes()) {
    52→            builder.startObject();
    53→            builder.field("node_id", nodeResp.getNode().getId());
    54→            builder.field("node_name", nodeResp.getNode().getName());
    55→            nodeResp.toXContent(builder, params);
    56→            builder.endObject();
    57→        }
    58→        builder.endArray();
    59→
    60→        // 실패한 노드
    61→        if (hasFailures()) {
    62→            builder.startArray("failures");
    63→            for (FailedNodeException failure : failures()) {
    64→                builder.startObject();
    65→                builder.field("node_id", failure.nodeId());
    66→                builder.field("reason", failure.getMessage());
    67→                builder.endObject();
    68→            }
    69→            builder.endArray();
    70→        }
    71→
    72→        builder.field("all_successful", isAllSuccessful());
    73→        builder.endObject();
    74→        return builder;
    75→    }
