    81→        return failures().isEmpty() &&
    82→               getNodes().stream().allMatch(ReloadDictNodeResponse::isSuccess);
    83→    }
    84→
    85→    /**
    86→     * 전체 리로드 소요시간 (가장 긴 노드 기준)
    87→     */
    88→    public long getMaxReloadTime() {
    89→        return getNodes().stream()
    90→                .mapToLong(ReloadDictNodeResponse::getReloadTimeMs)
    91→                .max()
    92→                .orElse(0);
    93→    }
    94→}
