            log.error("[{}] Dictionary reload failed: {}", localNode.name, e.message, e)
            ReloadDictNodeResponse(localNode, false, e.message, elapsed, 0)
        }
    }

    private fun getDictionarySize(dictionary: ProductNameDictionary): Int {
        return try {
            dictionary.getDictionaryMap()?.size ?: 0
        } catch (e: Exception) {
            log.debug("Failed to get dictionary size", e)
            0
        }
    }

