import java.io.IOException

class ReloadDictNodesResponse : BaseNodesResponse<ReloadDictNodeResponse>, ToXContentObject {

    constructor(clusterName: ClusterName, nodes: List<ReloadDictNodeResponse>, failures: List<FailedNodeException>)
        : super(clusterName, nodes, failures)

    @Throws(IOException::class)
    constructor(input: StreamInput) : super(input)

    @Throws(IOException::class)
    override fun readNodesFrom(input: StreamInput): List<ReloadDictNodeResponse> {
        return input.readCollectionAsList(::ReloadDictNodeResponse)
    }

    @Throws(IOException::class)
    override fun writeNodesTo(out: StreamOutput, nodes: List<ReloadDictNodeResponse>) {
        out.writeCollection(nodes)
    }

    @Throws(IOException::class)
    override fun toXContent(builder: XContentBuilder, params: ToXContent.Params): XContentBuilder {
        builder.startObject()
        builder.field("cluster_name", clusterName.value())

        builder.startArray("nodes")
        for (nodeResp in nodes) {
            builder.startObject()
            builder.field("node_id", nodeResp.node.id)
            builder.field("node_name", nodeResp.node.name)
            nodeResp.toXContent(builder, params)
            builder.endObject()
        }
        builder.endArray()

        if (hasFailures()) {
            builder.startArray("failures")
            for (failure in failures()) {
                builder.startObject()
                builder.field("node_id", failure.nodeId())
                builder.field("reason", failure.message)
                builder.endObject()
            }
            builder.endArray()
        }

        builder.field("all_successful", isAllSuccessful)
        builder.endObject()
        return builder
    }

    val isAllSuccessful: Boolean
        get() = failures().isEmpty() && nodes.all { it.isSuccess }

    val maxReloadTime: Long
        get() = nodes.maxOfOrNull { it.reloadTimeMs } ?: 0L
}

